code_sketch:
abstract record Expr;
sealed record Literal(int Value) : Expr;
sealed record Binary(Expr Left, string Op, Expr Right) : Expr;   // named children

static string Print(Expr e) => e switch {
    Literal l => l.Value.ToString(),
    Binary b  => $"({Print(b.Left)} {b.Op} {Print(b.Right)})",
    _ => throw new UnreachableException()
};

variants.code_sketch:
abstract class Expr { public abstract string Print(); }
sealed class Binary : Expr {
    public Expr Left { get; } public string Op { get; } public Expr Right { get; }  // named children
    public Binary(Expr left, string op, Expr right) => (Left, Op, Right) = (left, op, right);
    public override string Print() => $"({Left.Print()} {Op} {Right.Print()})";
}

